args<-commandArgs(TRUE);A<-normalizePath(args[1],winslash='/');C<-file.path(A,'02_CONTROLLI');suppressPackageStartupMessages(library(ade4));rd<-function(s){p<-list.files(C,pattern='^Table_S4_',full.names=TRUE);d<-read.delim(file.path(p,paste0(s,'.tsv')),check.names=FALSE);m<-as.matrix(d[-1]);rownames(m)<-d[[1]];m};clr<-function(P){P<-P/rowSums(P);L<-log(P+min(P[P>0])/2);L-rowMeans(L)};K<-rd('Kraken_100');M<-rd('MetaPhlAn_99');common<-sort(intersect(rownames(K),rownames(M)));X<-clr(K)[common,];Y<-clr(M)[common,];co<-coinertia(dudi.pca(X,center=TRUE,scale=FALSE,scannf=FALSE,nf=2),dudi.pca(Y,center=TRUE,scale=FALSE,scannf=FALSE,nf=2),scannf=FALSE,nf=2);options(digits=17);cat('ADE4_COINERTIA_FULL_TABLE_RV',co$RV,'rank',co$rank,'kept_axes',co$nf,'\n');write.table(data.frame(method='ade4 dudi.pca(full CLR tables, scale=FALSE, nf=2) + coinertia(nf=2)',RV=co$RV,kept_axes=co$nf,rank=co$rank),file.path(C,'RV_ADE4_VERIFICATION.tsv'),sep='\t',row.names=FALSE)
